      <label for="email">Email address</label>
      <!-- type="text" on purpose: <input type="email"> rejects Unicode local
           parts (josé@example.fr) in every browser, and browsers disagree on
           internationalized domains (Chromium rewrites them to xn-- form,
           WebKit rejects them). The script checks the address instead. -->
      <input id="email" name="email" type="text" inputmode="email"
             autocomplete="email" autocapitalize="none" autocorrect="off"
             spellcheck="false" required aria-describedby="email-error">
