<script>
(function () {
  'use strict';

  var form = document.getElementById('signup');
  var success = document.getElementById('success');
  var fields = ['fullname', 'email', 'website', 'password'].map(function (id) {
    return document.getElementById(id);
  });

  /* ---------- Domain names ---------- */

  // Checks a name already in ASCII (A-label) form: dot-separated labels of
  // 1–63 letters, digits or hyphens, 253 characters at most in total.
  // The top-level domain is two or more letters of ANY length (.fr, .corsica,
  // .international) or an xn-- A-label (.xn--p1ai is .рф). No list of TLDs.
  function isAsciiHostname(host) {
    if (!host || host.length > 253) return false;
    var labels = host.toLowerCase().split('.');
    if (labels.length < 2) return false;
    var label = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$/;
    if (!labels.every(function (l) { return label.test(l); })) return false;
    var tld = labels[labels.length - 1];
    return /^[a-z]{2,}$/.test(tld) || /^xn--[a-z0-9-]+$/.test(tld);
  }

  // Converts a domain typed by the user (société.fr, 例子.中国, EXAMPLE.com)
  // to its ASCII form using the browser's own IDNA / UTS #46 implementation
  // (the URL parser). Returns null when it is not a valid domain name.
  function domainToAscii(domain) {
    if (!domain || /[\s\/\\?#@:%\[\]]/.test(domain)) return null;
    var host;
    try {
      host = new URL('http://' + domain).hostname;
    } catch (e) {
      return null;
    }
    return isAsciiHostname(host) ? host : null;
  }

  /* ---------- Field checks: each returns { error, ascii? } ---------- */

  function checkFullname(value) {
    return { error: value.trim() ? '' : 'Enter your full name.' };
  }

  // Deliberately minimal: one @, a non-empty local part without spaces
  // (Unicode, +, ' and other symbols are all fine), and a valid domain.
  function checkEmail(value) {
    var v = value.trim();
    if (!v) return { error: 'Enter your email address.' };
    if (/\s/.test(v)) return { error: 'An email address cannot contain spaces.' };
    var parts = v.split('@');
    if (parts.length !== 2) return { error: 'An email address needs exactly one @ sign.' };
    if (!parts[0]) return { error: 'Add the part before the @ sign.' };
    var asciiDomain = domainToAscii(parts[1]);
    if (!asciiDomain) {
      return { error: 'The part after the @ must be a domain name, such as example.com or société.fr.' };
    }
    return { error: '', ascii: parts[0] + '@' + asciiDomain };
  }

  function checkWebsite(value) {
    var invalid = 'Enter a web address such as example.org or https://société.fr.';
    var v = value.trim();
    if (!v) return { error: '', ascii: '' }; // optional field
    if (/\s/.test(v)) return { error: 'A web address cannot contain spaces.' };
    var hasScheme = /^[a-z][a-z0-9+.-]*:\/\//i.test(v);
    var url;
    try {
      url = new URL(hasScheme ? v : 'https://' + v);
    } catch (e) {
      return { error: invalid };
    }
    if (url.protocol !== 'http:' && url.protocol !== 'https:') {
      return { error: 'The web address must start with http:// or https://.' };
    }
    if (url.username || url.password) return { error: invalid };
    // url.hostname is already converted to A-labels by the URL parser.
    if (!isAsciiHostname(url.hostname.replace(/\.$/, ''))) return { error: invalid };
    return { error: '', ascii: url.href };
  }

  function checkPassword(value) {
    if (!value) return { error: 'Choose a password.' };
    if (Array.from(value).length < 8) return { error: 'Use at least 8 characters.' };
    return { error: '' };
  }

  var checks = {
    fullname: checkFullname,
    email: checkEmail,
    website: checkWebsite,
    password: checkPassword
  };

  /* ---------- Wiring ---------- */

  function validateField(input) {
    var result = checks[input.name](input.value);
    document.getElementById(input.id + '-error').textContent = result.error;
    if (result.error) {
      input.setAttribute('aria-invalid', 'true');
    } else {
      input.removeAttribute('aria-invalid');
    }
    return result;
  }

  fields.forEach(function (input) {
    // Check when the user leaves a field…
    input.addEventListener('blur', function () {
      if (input.value !== '') validateField(input);
    });
    // …and clear the error as soon as it is corrected.
    input.addEventListener('input', function () {
      success.hidden = true;
      if (input.getAttribute('aria-invalid') === 'true') validateField(input);
    });
  });

  form.addEventListener('submit', function (event) {
    var results = {};
    var firstInvalid = null;

    fields.forEach(function (input) {
      results[input.name] = validateField(input);
      if (results[input.name].error && !firstInvalid) firstInvalid = input;
    });

    if (firstInvalid) {
      event.preventDefault();
      success.hidden = true;
      firstInvalid.focus();
      return;
    }

    form.elements.email_ascii.value = results.email.ascii;
    form.elements.website_ascii.value = results.website.ascii;

    // No endpoint configured: stay on the page and confirm.
    // With an action attribute set, the form is submitted normally.
    if (!form.getAttribute('action')) {
      event.preventDefault();
      success.hidden = false;
    }
  });
})();
</script>
</body>
